1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { SalaoService } from './salao.service';
4	import type { ItemComandaBody } from './salao.service';
5	
6	// PDV do caixa (lado estabelecimento): ações de cancelar/desconto/acréscimo/pagar
7	// são exclusivas do dono (RestaurantOwnerGuard) — o garçom nunca tem acesso a
8	// essas rotas (ver salao.controller.ts, que só cobre abrir/adicionar/enviar/fechar).
9	@Injectable()
10	export class SalaoPdvService {
11	  constructor(
12	    private supabase: SupabaseService,
13	    private salaoService: SalaoService,
14	  ) {}
15	
16	  async mesas(restaurantId: number) {
17	    const { data: mesas, error } = await this.supabase.client
18	      .from('mesas')
19	      .select('id, numero, nome, status')
20	      .eq('restaurant_id', restaurantId)
21	      .order('numero', { ascending: true });
22	    if (error) throw error;
23	
24	    const { data: comandas } = await this.supabase.client
25	      .from('orders')
26	      .select('id, mesa_id, total, status, numero_comanda, cliente_mesa_nome, garcons(nome)')
27	      .eq('restaurant_id', restaurantId)
28	      .eq('canal', 'presencial')
29	      .in('status', ['aberta', 'fechada_garcom'])
30	      .not('mesa_id', 'is', null);
31	
32	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
33	
34	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
35	  }
36	
37	  async comandasAbertas(restaurantId: number) {
38	    const { data, error } = await this.supabase.client
39	      .from('orders')
40	      .select('id, mesa_id, cliente_mesa_nome, cliente_mesa_telefone, total, status, payment_method, numero_comanda, created_at, mesas(numero, nome), garcons(nome)')
41	      .eq('restaurant_id', restaurantId)
42	      .eq('canal', 'presencial')
43	      .in('status', ['aberta', 'fechada_garcom'])
44	      .order('created_at', { ascending: false });
45	    if (error) throw error;
46	    return data;
47	  }
48	
49	  private async buscarComanda(id: number, restaurantId: number) {
50	    const { data } = await this.supabase.client
51	      .from('orders')
52	      .select('*, mesas(numero, nome), garcons(id, nome)')
53	      .eq('id', id)
54	      .eq('restaurant_id', restaurantId)
55	      .eq('canal', 'presencial')
56	      .maybeSingle();
57	    if (!data) throw new NotFoundException('Comanda não encontrada');
58	    return data;
59	  }
60	
61	  async comandaDetalhe(id: number, restaurantId: number) {
62	    const comanda = await this.buscarComanda(id, restaurantId);
63	    const { data: itens } = await this.supabase.client
64	      .from('order_items')
65	      .select('id, product_id, quantity, unit_price, observacao, status, enviado_em, products(name, image_url)')
66	      .eq('order_id', id)
67	      .order('id', { ascending: true });
68	    const { data: pagamentos } = await this.supabase.client
69	      .from('comanda_pagamentos')
70	      .select('id, valor, forma_pagamento, origem, criado_em')
71	      .eq('order_id', id)
72	      .order('criado_em', { ascending: true });
73	    const saldo = await this.salaoService.saldoDevedor(id);
74	    return { ...comanda, itens, pagamentos: pagamentos ?? [], saldo };
75	  }
76	
77	  // Pagamento parcial registrado pelo caixa — mesma regra do garçom (não fecha sozinho).
78	  async registrarPagamentoParcial(id: number, restaurantId: number, valor: number, formaPagamento: string) {
79	    const comanda = await this.buscarComanda(id, restaurantId);
80	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
81	      throw new BadRequestException('Comanda já foi paga ou cancelada');
82	    }
83	    return this.salaoService.registrarPagamento(id, 'estabelecimento', valor, formaPagamento);
84	  }
85	
86	  async aplicarDesconto(id: number, restaurantId: number, valor: number) {
87	    if (valor < 0) throw new BadRequestException('Desconto não pode ser negativo');
88	    await this.buscarComanda(id, restaurantId);
89	    const { data, error } = await this.supabase.client
90	      .from('orders')
91	      .update({ desconto_valor: valor })
92	      .eq('id', id)
93	      .select()
94	      .single();
95	    if (error) throw error;
96	    return data;
97	  }
98	
99	  async aplicarAcrescimo(id: number, restaurantId: number, valor: number) {
100	    if (valor < 0) throw new BadRequestException('Acréscimo não pode ser negativo');
101	    await this.buscarComanda(id, restaurantId);
102	    const { data, error } = await this.supabase.client
103	      .from('orders')
104	      .update({ acrescimo_valor: valor })
105	      .eq('id', id)
106	      .select()
107	      .single();
108	    if (error) throw error;
109	    return data;
110	  }
111	
112	  // Dono/caixa inclui item direto na comanda (o garçom não precisa estar envolvido) —
113	  // vai pendente e já sai imprimindo/pra fila igual quando o garçom manda.
114	  async adicionarItens(id: number, restaurantId: number, itens: ItemComandaBody[]) {
115	    if (!itens?.length) throw new BadRequestException('Informe ao menos 1 item');
116	
117	    const comanda = await this.buscarComanda(id, restaurantId);
118	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda não está aberta');
119	
120	    const prodIds = itens.map((i) => i.product_id);
121	    const { data: produtos, error: errProd } = await this.supabase.client
122	      .from('products')
123	      .select('id, price, is_active')
124	      .in('id', prodIds);
125	    if (errProd) throw errProd;
126	
127	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
128	    for (const item of itens) {
129	      const prod = prodMap[item.product_id];
130	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
131	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
132	    }
133	
134	    const { error } = await this.supabase.client.from('order_items').insert(
135	      itens.map((i) => ({
136	        order_id: id,
137	        product_id: i.product_id,
138	        quantity: i.quantity,
139	        unit_price: prodMap[i.product_id].price,
140	        observacao: i.observacao?.trim() || null,
141	        status: 'pendente',
142	      })),
143	    );
144	    if (error) throw error;
145	
146	    const { data: todosItens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', id);
147	    const total = (todosItens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
148	    await this.supabase.client.from('orders').update({ total: parseFloat(total.toFixed(2)) }).eq('id', id);
149	
150	    await this.salaoService.enviarItensComoRestaurante(id, comanda);
151	    return this.comandaDetalhe(id, restaurantId);
152	  }
153	
154	  // Estabelecimento pode remover qualquer item (pendente ou já enviado) — diferente do
155	  // garçom, que só mexe em item ainda não enviado (ver salao.service.ts).
156	  async removerItem(comandaId: number, restaurantId: number, itemId: number) {
157	    const comanda = await this.buscarComanda(comandaId, restaurantId);
158	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
159	      throw new BadRequestException('Comanda já foi paga ou cancelada');
160	    }
161	
162	    const { data: item } = await this.supabase.client
163	      .from('order_items')
164	      .select('id')
165	      .eq('id', itemId)
166	      .eq('order_id', comandaId)
167	      .maybeSingle();
168	    if (!item) throw new NotFoundException('Item não encontrado');
169	
170	    const { error } = await this.supabase.client.from('order_items').delete().eq('id', itemId);
171	    if (error) throw error;
172	
173	    const { data: todosItens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', comandaId);
174	    const total = (todosItens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
175	    await this.supabase.client.from('orders').update({ total: parseFloat(total.toFixed(2)) }).eq('id', comandaId);
176	
177	    return this.comandaDetalhe(comandaId, restaurantId);
178	  }
179	
180	  // Troca o garçom responsável por uma comanda em andamento (ex: troca de turno).
181	  async transferirGarcom(id: number, restaurantId: number, novoGarcomId: number) {
182	    await this.buscarComanda(id, restaurantId);
183	
184	    const { data: garcom } = await this.supabase.client
185	      .from('garcons')
186	      .select('id, ativo')
187	      .eq('id', novoGarcomId)
188	      .eq('restaurant_id', restaurantId)
189	      .maybeSingle();
190	    if (!garcom) throw new NotFoundException('Garçom não encontrado');
191	    if (!garcom.ativo) throw new BadRequestException('Garçom está desativado');
192	
193	    const { error } = await this.supabase.client.from('orders').update({ garcom_id: novoGarcomId }).eq('id', id);
194	    if (error) throw error;
195	    return { ok: true };
196	  }
197	
198	  // Transfere/junta uma comanda em andamento — dois casos:
199	  // 1) mesa_id de destino livre: só move a comanda pra essa mesa (troca física simples).
200	  // 2) mesa_id de destino ocupada, ou comanda_destino_id direto: junta tudo (itens +
201	  //    pagamentos parciais já registrados) na comanda de destino e encerra a origem.
